INF = 10 ** 20


def solve(N, A, B):
    dp = {A[0]: 0, A[0] + 1: B[0], A[0] + 2: B[0] * 2}
    for i in range(1, N):
        ndp = {}

        h = A[i]
        for ph, c in dp.items():
            for inc in range(3):
                nh = h + inc
                if ph == nh:
                    continue
                if nh not in ndp:
                    ndp[nh] = INF
                ndp[nh] = min(ndp[nh], c + B[i] * inc)

        dp = ndp

    return min(dp.values())


