            d = b[1:i] + b[i+1:]
            return self.dfs(c,d) + 1
        else:
            res = float('inf')
            for i in one:
                c = a[i] + a[1:i] + a[i+1:]
                d = b[:i]+b[i+1:]
                res= min(res,self.dfs(c,d)+1)

