class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)

        def compLen(c):
            return 1 + len(str(c)) if c > 1 else 1

        @lru_cache(None)
        def dp(i, k): # return {head: (len, -head_count)}
            if (n - i) <= k:
                return {} # remove all
            x, res = s[i], {}
            # remove
            if k:
                res = dp(i + 1, k - 1)
            # keep
            keep = dp(i + 1, k)
            t = [(1 + min((leng for leng, _ in list(keep.values())), default=0), -1)]
            if x in keep:
                leng, negc = keep[x]
                leng, negc = (leng - compLen(-negc) + compLen(-negc + 1),
                              negc - 1)
                t.append((leng, negc))
            if x in res:
                t.append(res[x])
            res[x] = min(t)
            return res

        m = dp(0, k)
        return min((leng for leng, _ in list(m.values())), default = 0)

class Solution:
     def trap(self, height):
         """
         :type height: List[int]
         :rtype: int
         """
         if not height:
             return 0
         result = 0
         left = 0
         right = len(height) - 1
         while left < right:
             if height[left] <= height[right]:
                 tmp = height[left]
                 left += 1
                 while left < right and height[left] <= tmp:
                     result += tmp - height[left]
                     left += 1
             else:
                 tmp = height[right]
                 right -= 1
                 while left < right and height[right] <= tmp:
                     result += tmp - height[right]
                     right -=1 
         return result

