             return ret
         else:
             return -1

class Solution:
    def maxDistance(self, grid: List[List[int]]) -> int:

        from collections import deque

        queue = deque()
        for i, row in enumerate(grid):
            for j, cell in enumerate(row):
                if cell == 1:
                    queue.append((i, j, None, None))

        dist = {}
        while queue:

            i, j, previ, prevj = queue.popleft()
            if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
                continue
            if (i, j) not in dist:
                dist[(i, j)] = 1 + dist.get((previ, prevj), -1)
                # if previ is None and prevj is None:
                #     dist[(i, j)] = 0
                # else:
                #     dist[(i, j)] = 1 + dist[(previ, prevj)]
                for di, dj in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
                    newi, newj = i +di, j + dj
                    queue.append((newi, newj, i, j))

        ans = max(list(dist.values()), default=-1)
        return ans if ans != 0 else -1

class Solution(object):
     def convert(self, s, numRows):
         """
         :type s: str
         :type numRows: int
         :rtype: str
         """
         if numRows == 1:
             return s
         zigzag = ['' for i in range(numRows)] 
         row = 0                                
         step = 1                              
         for c in s:
             if row == 0:
                 step = 1
             if row == numRows - 1:
                 step = -1
             zigzag[row] += c
             row += step
         return ''.join(zigzag)

