class Solution:
    def helper(self, l1, l2):
        if len(l1) < 1 and len(l2) <2:
            sum_remove = 0
        elif len(l1) < 1:
            sum_remove = min(l2)
            l2.remove(sum_remove)
            sum_remove += min(l2)

        elif len(l2) <2:
            sum_remove = min(l1)

        else:
            sum_remove1 = min(l1)
            sum_remove2 = min(l2)
            l2.remove(sum_remove2)
            sum_remove2 += min(l2)
            sum_remove = min(sum_remove1, sum_remove2)

