  else:
   dict1[arr[i]] = 1
 l1 = [0]+list(dict1.keys())
 v = min(k, len(l1))
 dp = [[0 for _ in range(v+1)]for _ in range(len(l1))]
 dp[0][0] = 1
 for i in range(1, len(l1)):
  dp[i][0] = 1
  for j in range(1, v+1):
