  fball[r][n] = 1
  return
 if n > 0 and r > 0 and n > r:
  fball[r][n] = (fball[r-1][n-1]%MOD + (r*fball[r][n-1])%MOD )%MOD
  return
 fball[r][n] = 0


def calASNum(n, r):
