def phi(n):
	res = n
	i = 2
	while i*i<=n:
		if n%i==0:
			res/=i
			res*=(i-1)

			while n%i==0:
				n/=i
		i+=1

	if n>1:
		res/=n
		res*=(n-1)

	return int(res)

