    a = list(zip(l, l[1:]))
    if len(a) == 0:
        return True
    else:
        p = a[0][1] / a[0][0]
        if p <= 1 or int(p) != p:
            return False
        for i in range(1, len(a)):
            if a[i][1] / a[i][0] != p:
                return False
        return True


