    def ctlt(arr, val):
        # find number of values in sorted arr < val
        if arr[0] >= val: return 0
        lo = 0
        hi = len(arr)
        while hi-lo > 1:
            md = (hi+lo)//2
            if arr[md]<val:
                lo = md
            else:
                hi = md

        return hi

