def codn1(s1,s2,p):
	c=0
	ind=0
	for i in range(len(s1)):
		if s1[i]!=s2[i]:
			c+=1
			ind=i
	if c>1 or ind==len(s1)-1:
		return 0
	if s1[ind]>s2[ind] and s1[ind] in s2[ind+1:]:
		p[0]=True
	if s1[ind]<s2[ind] and s2[ind] in s1[ind+1:]:
		p[1]=True
	return 1

def codn2(s1,s2):
	if len(s1)<len(s2):
		for i in range(len(s2)):
			if s2[:i]+s2[i+1:]==s1:
				return 1
	else:
		for i in range(len(s1)):
			if s1[:i]+s1[i+1:]==s2:
				return 2


