  return -1
 else:
  splits=[len(list(x))+1 for num,x in groupby(gcds) if num==0]
  # print(splits)
  if gcds[0]==gcds[-1]==0:
   splits[0] += splits[-1]-1
   splits = splits[:-1]
  return splits

