    def getChar(self, s, i):
        char = ''
        count = 0
        while i >= 0 and not char:
            if s[i] == '#':
                count += 1
            elif count == 0:
                char = s[i]
            else:
                count -= 1
            i -= 1
        return char, i

class Solution:
     def pivotIndex(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         left, right = 0, sum(nums)
         for index, num in enumerate(nums):
             right -= num
             if left == right:
                 return index
             left += num
         return -1

