def addmod(left, right, modulo=1000000007):
    res = left + right
    if res >= modulo:
        res -= modulo
    return res

def counter(a, m, d):
    res = [0, ] * (2*m)
    res[0] = 1
    shift = 1
    for pos in range(len(a), 0, -1):
        ptype = pos & 1
        cur = int(a[pos-1])
        tres = [0, ] * (2*m)
        for i in range(10):
            if ptype==1 and i == d:
                continue
            if ptype==0 and i != d:
                continue
            k = (i * shift) % m
            for j in range(m):
                k2 = k*2
                j2 = j*2
                if i < cur:
                    tres[k2+0] = addmod(tres[k2+0], addmod(res[j2+0], res[j2+1]))
                elif i == cur:
                    tres[k2+0] = addmod(tres[k2+0], res[j2+0])
                    tres[k2+1] = addmod(tres[k2+1], res[j2+1])
                else:
                    tres[k2+1] = addmod(tres[k2+1], addmod(res[j2+0], res[j2+1]))
                k = k+1 if k+1<m else 0
        res = tres
        shift = (shift * 10) % m
    return res[0]


