def split_exp(n):
    dot = n.find('.')
    if dot == -1: dot = len(n)
    return [d+"0"*(dot-i-1) if i<dot else ".{}{}".format("0"*(i-dot-1), d)
            for i,d in enumerate(n) if i != dot and d != '0']

def to_bytes(n):
    if not n:
        return ['00000000']

    res = []
    while n:
        res.append('{:08b}'.format(n % 256))
        n //= 256

    return res[::-1]

