    return dividend

def build_palindrome(s):
    for n in range(len(s), -1, -1):
        if s[:n] == s[:n][::-1]:
            return s[n:][::-1] + s
        if s[-n:] == s[-n:][::-1]:
            return s + s[:-n][::-1]

def pattern(n):
    lines = []
    for i in range(1, n + 1):
        line = ' ' * (n - i)
        line += ''.join(str(j % 10) for j in range(1, i + 1))
        line += line[::-1][1:]
        lines.append(line)
    return '\n'.join(lines + lines[::-1][1:])

